SET NOCOUNT ON;SET XACT_ABORT ON;ALTER INDEX CX_FF100 ON lab.FF100 REBUILD WITH(FILLFACTOR=100,MAXDOP=1);ALTER INDEX CX_FF080 ON lab.FF080 REBUILD WITH(FILLFACTOR=80,MAXDOP=1);INSERT lab.Evidence SELECT 'REBUILT',o.name,COALESCE(s.leaf_allocation_count,0),p.page_count,p.avg_page_space_used_in_percent,p.avg_fragmentation_in_percent FROM sys.objects o CROSS APPLY sys.dm_db_index_physical_stats(DB_ID(),o.object_id,1,NULL,'DETAILED')p OUTER APPLY sys.dm_db_index_operational_stats(DB_ID(),o.object_id,1,NULL)s WHERE o.object_id IN(OBJECT_ID(N'lab.FF100'),OBJECT_ID(N'lab.FF080')) AND p.index_level=0 AND p.alloc_unit_type_desc='IN_ROW_DATA';PRINT 'SQLPERF_SUMMARY|PASS|OK';
